func queueShelfPurge(u *repox.Unit, name string) (keep *bool) {
	keep = new(bool)
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error {
			*keep = refs.KeepOnPurge(ctx, "catalog.example.com/Shelf", name)
			return nil
		})
	}
	return keep
}
